import { Debug } from './debug'\nimport { isDriverAdapterError } from './error'\nimport { err, ok, Result } from './result'\nimport type {\n  ErrorCapturingSqlDriverAdapter,\n  ErrorCapturingSqlDriverAdapterFactory,\n  ErrorCapturingSqlMigrationAwareDriverAdapterFactory,\n  ErrorCapturingTransaction,\n  ErrorRecord,\n  ErrorRegistry,\n  SqlDriverAdapter,\n  SqlDriverAdapterFactory,\n  SqlMigrationAwareDriverAdapterFactory,\n  Transaction,\n} from './types'\n\nconst debug = Debug('driver-adapter-utils')\n\nclass ErrorRegistryInternal implements ErrorRegistry {\n  private registeredErrors: ErrorRecord[] = []\n\n  consumeError(id: number): ErrorRecord | undefined {\n    return this.registeredErrors[id]\n  }\n\n  registerNewError(error: unknown) {\n    let i = 0\n    while (this.registeredErrors[i] !== undefined) {\n      i++\n    }\n    this.registeredErrors[i] = { error }\n    return i\n  }\n}\n\nfunction copySymbolsFromSource<S extends object, T extends object>(source: S, target: T) {\n  const symbols = Object.getOwnPropertySymbols(source)\n  const symbolObject = Object.fromEntries(symbols.map((symbol) => [symbol, true]))\n  Object.assign(target, symbolObject)\n}\n\nexport const bindMigrationAwareSqlAdapterFactory = (\n  adapterFactory: SqlMigrationAwareDriverAdapterFactory,\n): ErrorCapturingSqlMigrationAwareDriverAdapterFactory => {\n  const errorRegistry = new ErrorRegistryInternal()\n\n  const boundFactory: ErrorCapturingSqlMigrationAwareDriverAdapterFactory = {\n    adapterName: adapterFactory.adapterName,\n    provider: adapterFactory.provider,\n    errorRegistry,\n    connect: async (...args) => {\n      const ctx = await wrapAsync(errorRegistry, adapterFactory.connect.bind(adapterFactory))(...args)\n      return ctx.map((ctx) => bindAdapter(ctx, errorRegistry))\n    },\n    connectToShadowDb: async (...args) => {\n      const ctx = await wrapAsync(errorRegistry, adapterFactory.connectToShadowDb.bind(adapterFactory))(...args)\n      return ctx.map((ctx) => bindAdapter(ctx, errorRegistry))\n    },\n  }\n\n  copySymbolsFromSource(adapterFactory, boundFactory)\n\n  return boundFactory\n}\n\nexport const bindSqlAdapterFactory = (\n  adapterFactory: SqlDriverAdapterFactory,\n): ErrorCapturingSqlDriverAdapterFactory => {\n  const errorRegistry = new ErrorRegistryInternal()\n\n  const boundFactory: ErrorCapturingSqlDriverAdapterFactory = {\n    adapterName: adapterFactory.adapterName,\n    provider: adapterFactory.provider,\n    errorRegistry,\n    connect: async (...args) => {\n      const ctx = await wrapAsync(errorRegistry, adapterFactory.connect.bind(adapterFactory))(...args)\n      return ctx.map((ctx) => bindAdapter(ctx, errorRegistry))\n    },\n  }\n\n  copySymbolsFromSource(adapterFactory, boundFactory)\n\n  return boundFactory\n}\n\n// *.bind(adapter) is required to preserve the `this` context of functions whose\n// execution is delegated to napi.rs.\nexport const bindAdapter = (\n  adapter: SqlDriverAdapter,\n  errorRegistry = new ErrorRegistryInternal(),\n): ErrorCapturingSqlDriverAdapter => {\n  const boundAdapter: ErrorCapturingSqlDriverAdapter = {\n    adapterName: adapter.adapterName,\n    errorRegistry,\n    queryRaw: wrapAsync(errorRegistry, adapter.queryRaw.bind(adapter)),\n    executeRaw: wrapAsync(errorRegistry, adapter.executeRaw.bind(adapter)),\n    executeScript: wrapAsync(errorRegistry, adapter.executeScript.bind(adapter)),\n    dispose: wrapAsync(errorRegistry, adapter.dispose.bind(adapter)),\n    provider: adapter.provider,\n    startTransaction: async (...args) => {\n      const ctx = await wrapAsync(errorRegistry, adapter.startTransaction.bind(adapter))(...args)\n      return ctx.map((ctx) => bindTransaction(errorRegistry, ctx))\n    },\n  }\n\n  if (adapter.getConnectionInfo) {\n    boundAdapter.getConnectionInfo = wrapSync(errorRegistry, adapter.getConnectionInfo.bind(adapter))\n  }\n\n  return boundAdapter\n}\n\n// *.bind(transaction) is required to preserve the `this` context of functions whose\n// execution is delegated to napi.rs.\nconst bindTransaction = (errorRegistry: ErrorRegistryInternal, transaction: Transaction): ErrorCapturingTransaction => {\n  return {\n    adapterName: transaction.adapterName,\n    provider: transaction.provider,\n    options: transaction.options,\n    queryRaw: wrapAsync(errorRegistry, transaction.queryRaw.bind(transaction)),\n    executeRaw: wrapAsync(errorRegistry, transaction.executeRaw.bind(transaction)),\n    commit: wrapAsync(errorRegistry, transaction.commit.bind(transaction)),\n    rollback: wrapAsync(errorRegistry, transaction.rollback.bind(transaction)),\n  }\n}\n\nfunction wrapAsync<A extends unknown[], R>(\n  registry: ErrorRegistryInternal,\n  fn: (...args: A) => Promise<R>,\n): (...args: A) => Promise<Result<R>> {\n  return async (...args) => {\n    try {\n      return ok(await fn(...args))\n    } catch (error) {\n      debug('[error@wrapAsync]', error)\n\n      // unwrap the cause of exceptions thrown by driver adapters if there is one\n      if (isDriverAdapterError(error)) {\n        return err(error.cause)\n      }\n      const id = registry.registerNewError(error)\n      return err({ kind: 'GenericJs', id })\n    }\n  }\n}\n\nfunction wrapSync<A extends unknown[], R>(\n  registry: ErrorRegistryInternal,\n  fn: (...args: A) => R,\n): (...args: A) => Result<R> {\n  return (...args) => {\n    try {\n      return ok(fn(...args))\n    } catch (error) {\n      debug('[error@wrapSync]', error)\n\n      // unwrap the cause of exceptions thrown by driver adapters if there is one\n      if (isDriverAdapterError(error)) {\n        return err(error.cause)\n      }\n      const id = registry.registerNewError(error)\n      return err({ kind: 'GenericJs', id })\n    }\n  }\n}\n", "import { Debug } from '@prisma/debug'\nimport { enginesVersion } from '@prisma/engines-version'\nimport type { BinaryPaths, DownloadOptions } from '@prisma/fetch-engine'\nimport { BinaryType } from '@prisma/fetch-engine'\nimport type { BinaryTarget } from '@prisma/get-platform'\nimport path from 'path'\n\nconst debug = Debug('prisma:engines')\nexport function getEnginesPath() {\n  return path.join(__dirname, '../')\n}\nexport const DEFAULT_CLI_QUERY_ENGINE_BINARY_TYPE = BinaryType.QueryEngineLibrary\n/**\n * Checks if the env override `PRISMA_CLI_QUERY_ENGINE_TYPE` is set to `library` or `binary`\n * Otherwise returns the default\n */\nexport function getCliQueryEngineBinaryType(clientEngineType = process.env.PRISMA_CLI_QUERY_ENGINE_TYPE): BinaryType {\n  if (clientEngineType === 'binary') {\n    return BinaryType.QueryEngineBinary\n  }\n  return DEFAULT_CLI_QUERY_ENGINE_BINARY_TYPE\n}\n\ntype EnsureSomeBinariesExistInput = {\n  clientEngineType: 'library' | 'binary' | 'client'\n  hasMigrateAdapterInConfig: boolean\n  download: (options: DownloadOptions) => Promise<BinaryPaths>\n}\n\nexport async function ensureNeededBinariesExist({\n  clientEngineType,\n  download,\n  hasMigrateAdapterInConfig,\n}: EnsureSomeBinariesExistInput) {\n  const binaryDir = path.join(__dirname, '../')\n\n  const binaries = {} as Record<BinaryType, string>\n\n  if (!hasMigrateAdapterInConfig) {\n    binaries[BinaryType.SchemaEngineBinary] = binaryDir\n  }\n\n  // query engine should only be downloaded if QE is enabled explicitly by specifying the\n  // engineType generator property.\n  const usesQueryCompiler = clientEngineType === 'client'\n\n  if (!usesQueryCompiler) {\n    const cliQueryEngineBinaryType = getCliQueryEngineBinaryType(clientEngineType)\n    binaries[cliQueryEngineBinaryType] = binaryDir\n  }\n\n  debug(`binaries to download ${Object.keys(binaries).join(', ')}`)\n\n  const binaryTargets = process.env.PRISMA_CLI_BINARY_TARGETS\n    ? (process.env.PRISMA_CLI_BINARY_TARGETS.split(',') as BinaryTarget[])\n    : undefined\n\n  await download({\n    binaries: binaries,\n    showProgress: true,\n    version: enginesVersion,\n    failSilent: false,\n    binaryTargets,\n  })\n}\n\nexport { enginesVersion } from '@prisma/en