}\n${potentialReasonMessage}\n\nDetails: ${error.message}`\n}\n", "import minIndent from 'min-indent';\n\nexport default function stripIndent(string) {\n\tconst indent = minIndent(string);\n\n\tif (indent === 0) {\n\t\treturn string;\n\t}\n\n\tconst regex = new RegExp(`^[ \\\\t]{${indent}}`, 'gm');\n\n\treturn string.replace(regex, '');\n}\n", "export const PRISMA_POSTGRES_PROVIDER = 'prisma+postgres'\n\nexport const PRISMA_POSTGRES_PROTOCOL = `${PRISMA_POSTGRES_PROVIDER}:`\n\ndeclare const prismaPostgresBrand: unique symbol\ndeclare const prismaPostgresDevBrand: unique symbol\n\nexport type PrismaPostgresUrl<T extends string | URL> = T & {\n  readonly [prismaPostgresBrand]: true\n}\n\nexport type PrismaPostgresDevUrl<T extends string | URL> = PrismaPostgresUrl<T> & {\n  readonly [prismaPostgresDevBrand]: true\n}\n\nexport function isPrismaPostgres<T extends string | URL>(\n  connectionString?: T,\n): connectionString is PrismaPostgresUrl<T> {\n  return connectionString?.toString().startsWith(`${PRISMA_POSTGRES_PROTOCOL}//`) ?? false\n}\n\nexport function isPrismaPostgresDev<T extends string | URL>(\n  connectionString?: T,\n): connectionString is PrismaPostgresDevUrl<T> {\n  if (!isPrismaPostgres(connectionString)) {\n    return false\n  }\n\n  const { host } = new URL(connectionString)\n\n  return host.includes('localhost') || host.includes('127.0.0.1') || host.includes('[::1]')\n}\n", "import type { BinaryTargetsEnvValue, GeneratorConfig } from '@prisma/generator'\nimport indent from 'indent-string'\n\nexport function printGeneratorConfig(config: GeneratorConfig): string {\n  return String(new GeneratorConfigClass(config))\n}\n\nexport class GeneratorConfigClass {\n  constructor(private readonly config: GeneratorConfig) {}\n  toString(): string {\n    const { config } = this\n    // parse & stringify trims out all the undefined values\n\n    const provider = config.provider.fromEnvVar ? `env(\"${config.provider.fromEnvVar}\")` : config.provider.value\n\n    const obj = JSON.parse(\n      JSON.stringify({\n        provider,\n        binaryTargets: getOriginalBinaryTargetsValue(config.binaryTargets),\n      }),\n    )\n\n    return `generator ${config.name} {\n${indent(printDatamodelObject(obj), 2)}\n}`\n  }\n}\n\nexport function getOriginalBinaryTargetsValue(binaryTargets: BinaryTargetsEnvValue[]) {\n  let value: string | string[] | undefined\n  if (binaryTargets.length > 0) {\n    const binaryTargetsFromEnvVar = binaryTargets.find((object) => object.fromEnvVar !== null)\n    if (binaryTargetsFromEnvVar) {\n      value = `env(\"${binaryTargetsFromEnvVar.fromEnvVar}\")`\n    } else {\n      value = binaryTargets.map((object) => (object.native ? 'native' : object.value))\n    }\n  } else {\n    value = undefined\n  }\n\n  return value\n}\n\nexport function printDatamodelObject(obj): string {\n  const maxLength = Object.keys(obj).reduce((max, curr) => Math.max(max, curr.length), 0)\n  return Object.entries(obj)\n    .map(([key, value]) => `${key.padEnd(maxLength)} = ${niceStringify(value)}`)\n    .join('\\n')\n}\n\nfunction niceStringify(value): any {\n  return JSON.parse(\n    JSON.stringify(value, (_, value) => {\n      if (Array.isArray(value)) {\n        return `[${value.map((element) => JSON.stringify(element)).join(', ')}]`\n      }\n      return JSON.stringify(value)\n    }),\n  )\n}\n", "import { blue, cyan, red, yellow } from 'kleur/colors'\n\nexport const tags = {\n  error: red('prisma:error'),\n  warn: yellow('prisma:warn'),\n  info: cyan('prisma:info'),\n  query: blue('prisma:query'),\n}\nexport const should = {\n  warn: () => !process.env.PRISMA_DISABLE_WARNINGS,\n}\nexport function log(...data: any[]) {\n  console.log(...data)\n}\nexport function warn(message: any, ...optionalParams: any[]) {\n  if (should.warn()) {\n    console.warn(`${tags.warn} ${message}`, ...optionalParams)\n  }\n}\nexport function info(message: any, ...optionalParams: any[]) {\n  console.info(`${tags.info} ${message}`, ...optionalParams)\n}\nexport function error(message: any, ...optionalParams: any[]) {\n  console.error(`${tags.error} ${message}`, ...optionalParams)\n}\nexport function query(message: any, ...optionalParams: any[]) {\n  console.log(`${tags.query} ${message}`, ...optionalParams)\n}\n", "/**\n * Assertion function for internal consistency checks that should never fail\n * in the correct code. It's purpose is pretty much:\n * - ensuring we get more helpful error message if invariant does not hold due to a bug\n * - have a better way of dealing with overly broad type definition than typecasting to `any`\n * or more narrow type.\n *\n * This function should be for assertions only on the values where we control both the input and the output: engine to client, generator to generated client, etc.\n * Don't use this function for assertion for any external input.\n *\n * @param condition\n * @param message\n */\nexport function assertAlways(condition: unknown, message: string): asserts condition {\n  if (!condition) {\n    throw new Error(\n      `${message}. This should never happen. If you see this error, please, open an issue at https://pris.ly/prisma-prisma-bug-report`,\n    )\n  }\n}\n", "/**\n * Utility function to ensure exhaustive checks for union types.\n *\n * @example\n *   ```ts\n *   declare const fruit: 'Apple' | 'Orange'\n *\n *   switch (fruit) {\n *     case 'Apple:\n *       // do apple things\n *       break;\n *     case 'Orange:\n *       // do orange things\n *       break;\n *     default:\n *       // in case `fruit` type will expand in the future,\n *       // we'll get a compile-time error here, listing all unhandled\n *       // cases\n *       assertNever(fruit, 'Unknown fruit')\n *   }\n *   ```\n * @param arg variable of the any union type. By the time `assertNever` is called\n * all possible cases of this union must already be handled\n * @param errorMessage error message to throw in runtime. Normally, should never happen\n * unless compile-time check is skipped\n */\nexport function assertNever(arg: never, errorMessage: string): never {\n  throw new Error(errorMessage)\n}\n", "export default function ansiRegex({onlyFirst = false} = {}) {\n\t// Valid string terminator sequences are BEL, ESC\\, and 0x9c\n\tconst ST = '(?:\\\\u0007|\\\\u001B\\\\u005C|\\\\u009C)';\n\tconst pattern = [\n\t\t`[\\\\u001B\\\\u009B][[\\\\]()#;?]*(?:(?:(?:(?:;[-a-zA-Z\\\\d\\\\/#&.:=?%@~_]+)*|[a-zA-Z\\\\d]+(?:;[-a-zA-Z\\\\d\\\\/#&.:=?%@~_]*)*)?${ST})`,\n\t\t'(?:(?:\\\\d{1,4}(?:;\\\\d{0,4})*)?[\\\\dA-PR-TZcf-nq-uy=><~]))',\n\t].join('|');\n\n\treturn new RegExp(pattern, onlyFirst ? undefined : 'g');\n}\n", "import ansiRegex from 'ansi-regex';\n\nconst regex = ansiRegex();\n\nexport default function stripAnsi(string) {\n\tif (typeof string !== 'string') {\n\t\tthrow new TypeError(`Expected a \\`string\\`, got \\`${typeof string}\\``);\n\t}\n\n\t// Even though the regex is global, we don't need to reset the `.lastIndex`\n\t// because unlike `.exec()` and `.test()`, `.replace()` does it automatically\n\t// and doing it manually has a performance penalty.\n\treturn string.replace(regex, '');\n}\n", "import path from 'path'\n\n/**\n * Normalize `filePath` to use forward slashes as a separator. `filePath` is\n * treated as a path specific to the current platform, so backslashes will only\n * be replaced with forward slashes on Windows. On other platforms, where a\n * backslash is a valid filename character, it will be treated as such and will\n * not be replaced.\n */\nexport function pathToPosix(filePath: string): string {\n  if (path.sep === path.posix.sep) {\n    return filePath\n  }\n  return filePath.split(path.sep).join(path.posix.sep)\n}\n\n/**\n * Returns the longest common path ancestor of the two paths (which may also be equal to one or both of them).\n * If they don't share a common ancestor (which may be the case on Windows if both paths are on different disks),\n * returns `undefined`.\n */\nexport function longestCommonPathPrefix(pathA: string, pathB: string): string | undefined {\n  if (!path.isAbsolute(pathA) || !path.isAbsolute(pathB)) {\n    throw new Error('longestCommonPathPrefix expects absolute paths')\n  }\n\n  if (process.platform === 'win32' && (pathA.startsWith('\\\\\\\\') || pathB.startsWith('\\\\\\\\'))) {\n    // Make both paths namespaced if at least one of them is.\n    pathA = path.toNamespacedPath(pathA)\n    pathB = path.toNamespacedPath(pathB)\n  }\n\n  const commonPrefix = longestCommonPrefix(pathA.split(path.sep), pathB.split(path.sep)).join(path.sep)\n\n  if (commonPrefix === '') {\n    return process.platform === 'win32' ? undefined : '/'\n  }\n\n  if (process.platform === 'win32' && ['\\\\', '\\\\\\\\?', '\\\\\\\\.'].includes(commonPrefix)) {\n    return undefined\n  }\n\n  if (process.platform === 'win32' && commonPrefix.endsWith(':')) {\n    // Disk specifier without a backslash at the end is not an absolute path on windows,\n    // it refers to current working directory on that disk.\n    return commonPrefix + '\\\\'\n  }\n\n  return commonPrefix\n}\n\nfunction longestCommonPrefix<T>(sequenceA: T[], sequenceB: T[]): T[] {\n  const maxLen = Math.min(sequenceA.length, sequenceB.length)\n  let sliceLen = 0\n\n  while (sliceLen <= maxLen && sequenceA[sliceLen] === sequenceB[sliceLen]) {\n    sliceLen++\n  }\n\n  return sequenceA.slice(0, sliceLen)\n}\n", "import Debug from '@prisma/debug'\nimport dotenv from 'dotenv'\nimport fs from 'fs'\nimport { bold, dim, red, underline, yellow } from 'kleur/colors'\nimport path from 'path'\n\nimport { dotenvExpand } from '../dotenvExpand'\n\nconst debug = Debug('prisma:tryLoadEnv')\n\ntype DotenvResult = dotenv.DotenvConfigOutput & {\n  ignoreProcessEnv?: boolean | undefined\n}\n\n// non-exported type from dotenv\ninterface DotenvLoadEnvResult {\n  message: string\n  path: string\n  dotenvResult: DotenvResult\n}\n\n// our type for loaded env data\nexport type LoadedEnv =\n  | {\n      message?: string\n      parsed: {\n        [x: string]: string\n      }\n    }\n  | undefined\n\nexport function tryLoadEnvs(\n  {\n    rootEnvPath,\n    schemaEnvPath,\n  }: {\n    rootEnvPath: string | null | undefined\n    schemaEnvPath: string | null | undefined\n  },\n  opts: { conflictCheck: 'warn' | 'error' | 'none' } = {\n    conflictCheck: 'none',\n  },\n): LoadedEnv {\n  const rootEnvInfo = loadEnv(rootEnvPath)\n  if (opts.conflictCheck !== 'none') {\n    // This will throw an error if there are conflicts\n    checkForConflicts(rootEnvInfo, schemaEnvPath, opts.conflictCheck)\n  }\n  // Only load the schema .env if it is not the same as root\n  let schemaEnvInfo: DotenvLoadEnvResult | null = null\n  if (!pathsEqual(rootEnvInfo?.path, schemaEnvPath)) {\n    schemaEnvInfo = loadEnv(schemaEnvPath)\n  }\n\n  // We didn't find a .env file.\n  if (!rootEnvInfo && !schemaEnvInfo) {\n    debug('No Environment variables loaded')\n  }\n\n  // Print the error if any (if internal dotenv readFileSync throws)\n  if (schemaEnvInfo?.dotenvResult.error) {\n    return console.error(red(bold('Schema Env Error: ')) + schemaEnvInfo.dotenvResult.error) as undefined\n  }\n  const messages = [rootEnvInfo?.message, schemaEnvInfo?.message].filter(Boolean)\n\n  return {\n    message: messages.join('\\n'),\n    parsed: {\n      ...rootEnvInfo?.dotenvResult?.parsed,\n      ...schemaEnvInfo?.dotenvResult?.parsed,\n    },\n  }\n}\n/**\n * Will throw an error if the file at `envPath` has env conflicts with `rootEnv`\n */\nfunction checkForConflicts(\n  rootEnvInfo: DotenvLoadEnvResult | null,\n  envPath: string | null | undefined,\n  type: 'warn' | 'error',\n) {\n  const parsedRootEnv = rootEnvInfo?.dotenvResult.parsed\n  const areNotTheSame = !pathsEqual(rootEnvInfo?.path, envPath)\n  if (parsedRootEnv && envPath && areNotTheSame && fs.existsSync(envPath)) {\n    const envConfig = dotenv.parse(fs.readFileSync(envPath))\n    const conflicts: string[] = []\n    for (const k in envConfig) {\n      if (parsedRootEnv[k] === envConfig[k]) {\n        conflicts.push(k)\n      }\n    }\n    if (conflicts.length > 0) {\n      // const message = `You are trying to load env variables which are already present in your project root .env\n      const relativeRootEnvPath = path.relative(process.cwd(), rootEnvInfo!.path)\n      const relativeEnvPath = path.relative(process.cwd(), envPath)\n      if (type === 'error') {\n        const message = `There is a conflict between env var${conflicts.length > 1 ? 's' : ''} in ${underline(\n          relativeRootEnvPath,\n        )} and ${underline(relativeEnvPath)}\nConflicting env vars:\n${conflicts.map((conflict) => `  ${bold(conflict)}`).join('\\n')}\n\nWe suggest to move the contents of ${underline(relativeEnvPath)} to ${underline(\n          relativeRootEnvPath,\n        )} to consolidate your env vars.\\n`\n        throw new Error(message)\n      } else if (type === 'warn') {\n        const message = `Conflict for env var${conflicts.length > 1 ? 's' : ''} ${conflicts\n          .map((c) => bold(c))\n          .join(', ')} in ${underline(relativeRootEnvPath)} and ${underline(relativeEnvPath)}\nEnv vars from ${underline(relativeEnvPath)} overwrite the ones from ${underline(relativeRootEnvPath)}\n      `\n        console.warn(`${yellow('warn(prisma)')} ${message}`)\n      }\n    }\n  }\n}\n\nexport function loadEnv(envPath: string | null | undefined): DotenvLoadEnvResult | null {\n  if (exists(envPath)) {\n    debug(`Environment variables loaded from ${envPath}`)\n\n    const dotenvOutput = dotenv.config({\n      path: envPath,\n      // Useful to debug dotenv parsing, prints errors & warnings\n      // Set to any value to enable\n      // Example for empty .env file\n      // [dotenv][DEBUG] did not match key and value when parsing line 1:\n      //\n      // Value needs to be null or undefined, false is truthy\n      // https://github.com/motdotla/dotenv/blob/7301ac9be0b2c766f865bbe24280bf82586d25aa/lib/main.js#L89-L91\n      debug: process.env.DOTENV_CONFIG_DEBUG ? true : undefined,\n    })\n\n    const dotenvExpandOutput = dotenvExpand(dotenvOutput)\n\n    return {\n      dotenvResult: dotenvExpandOutput,\n      message: dim(`Environment variables loaded from ${path.relative(process.cwd(), envPath)}`),\n      path: envPath,\n    }\n  } else {\n    debug(`Environment variables not found at ${envPath}`)\n  }\n  return null\n}\nexport function pathsEqual(path1: string | null | undefined, path2: string | null | undefined) {\n  return path1 && path2 && path.resolve(path1) === path.resolve(path2)\n}\n\nexport function exists(p: string | null | undefined): p is string {\n  return Boolean(p && fs.existsSync(p))\n}\n", "import type { DotenvConfigOutput } from 'dotenv'\n\n/**\n * Modified version of https://github.com/motdotla/dotenv-expand\n * Our version does only expand ${ENV} - curly braces but not without curly braces\n *\n * Original License from https://github.com/motdotla/dotenv-expand/blob/de9e5cb0215495452f475f5be4dea1580b8217cd/LICENSE\n * Copyright (c) 2016, Scott Motte\n * All rights reserved.\n *\n * Redistribution and use in source and binary forms, with or without\n * modification, are permitted provided that the following conditions are met:\n *\n * * Redistributions of source code must retain the above copyright notice, this\n *  list of conditions and the following disclaimer.\n *\n * * Redistributions in binary form must reproduce the above copyright notice,\n *  this list of conditions and the following disclaimer in the documentation\n *  and/or other materials provided with the distribution.\n *\n * THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS AND CONTRIBUTORS \"AS IS\"\n * AND ANY EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE\n * IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE ARE\n * DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT HOLDER OR CONTRIBUTORS BE LIABLE\n * FOR ANY DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL\n * DAMAGES (INCLUDING, BUT NOT LI