ptional\": true\n    }\n  },\n  \"sideEffects\": false\n}", "// https://runtime-keys.proposal.wintercg.org/\nexport type RuntimeName = 'workerd' | 'deno' | 'netlify' | 'node' | 'bun' | 'edge-light' | '' /* unknown */\n\n/**\n * Indicates if running in Node.js or a Node.js compatible runtime.\n *\n * **Note:** When running code in Bun and Deno with Node.js compatibility mode, `isNode` flag will be also `true`, indicating running in a Node.js compatible runtime.\n */\nconst isNode = () => globalThis.process?.release?.name === 'node'\n\n/**\n * Indicates if running in Bun runtime.\n */\nconst isBun = () => !!globalThis.Bun || !!globalThis.process?.versions?.bun\n\n/**\n * Indicates if running in Deno runtime.\n */\nconst isDeno = () => !!globalThis.Deno\n\n/**\n * Indicates if running in Netlify runtime.\n */\nconst isNetlify = () => typeof globalThis.Netlify === 'object'\n\n/**\n * Indicates if running in EdgeLight (Vercel Edge) runtime.\n */\nconst isEdgeLight = () => typeof globalThis.EdgeRuntime === 'object'\n\n/**\n * Indicates if running in Cloudflare Workers runtime.\n * See: https://developers.cloudflare.com/workers/runtime-apis/web-standards/#navigatoruseragent\n */\nconst isWorkerd = () => globalThis.navigator?.userAgent === 'Cloudflare-Workers'\n\nfunction detectRuntime(): RuntimeName {\n  // Note: we're currently not taking 'fastly' into account. Why?\n  const runtimeChecks = [\n    [isNetlify, 'netlify'],\n    [isEdgeLight, 'edge-light'],\n    [isWorkerd, 'workerd'],\n    [isDeno, 'deno'],\n    [isBun, 'bun'],\n    [isNode, 'node'],\n  ] as const\n\n  const detectedRuntime =\n    runtimeChecks\n      // TODO: Transforming destructuring to the configured target environment ('chrome58', 'edge16', 'firefox57', 'safari11') is not supported yet,\n      // so we can't write the following code yet:\n      // ```\n      // .flatMap(([isCurrentRuntime, runtime]) => isCurrentRuntime() ? [runtime] : [])\n      // ```\n      .flatMap((check) => (check[0]() ? [check[1]] : []))\n      .at(0) ?? ''\n\n  return detectedRuntime\n}\n\nconst runtimesPrettyNames = {\n  node: 'Node.js',\n  workerd: 'Cloudflare Workers',\n  deno: 'Deno and Deno Deploy',\n  netlify: 'Netlify Edge Functions',\n  'edge-light':\n    'Edge Runtime (Vercel Edge Functions, Vercel Edge Middleware, Next.js (Pages Router) Edge API Routes, Next.js (App Router) Edge Route Handlers or Next.js Middleware)',\n} as const\n\ntype GetRuntimeOutput = {\n  id: RuntimeName\n  prettyName: string\n  isEdge: boolean\n}\n\nexport function getRuntime(): GetRuntimeOutput {\n  const runtimeId = detectRuntime()\n\n  return {\n    id: runtimeId,\n    // Fallback to the runtimeId if the runtime is not in the list\n    prettyName: runtimesPrettyNames[runtimeId] || runtimeId,\n    isEdge: ['workerd', 'deno', 'netlify', 'edge-light'].includes(runtimeId),\n  }\n}\n", "import { GetPrismaClientConfig } from '@prisma/client-common'\n\nimport { Datasources } from '../../getPrismaClient'\nimport { getRuntime } from '../../utils/getRuntime'\nimport { PrismaClientInitializationError } from '../errors/PrismaClientInitializationError'\n\nexport function resolveDatasourceUrl({\n  inlineDatasources,\n  overrideDatasources,\n  env,\n  clientVersion,\n}: {\n  inlineDatasources: GetPrismaClientConfig['inlineDatasources']\n  overrideDatasources: Datasources\n  env: Record<string, string | undefined>\n  clientVersion: string\n}) {\n  let resolvedUrl: string | undefined\n  const datasourceName = Object.keys(inlineDatasources)[0]\n  const datasourceUrl = inlineDatasources[datasourceName]?.url\n  const overrideUrl = overrideDatasources[datasourceName]?.url\n\n  if (datasourceName === undefined) {\n    resolvedUrl = undefined\n  } else if (overrideUrl) {\n    resolvedUrl = overrideUrl\n  } else if (datasourceUrl?.value) {\n    resolvedUrl = datasourceUrl.value\n  } else if (datasourceUrl?.fromEnvVar) {\n    resolvedUrl = env[datasourceUrl.fromEnvVar]\n  }\n\n  // env var is set for use but url is undefined\n  if (datasourceUrl?.fromEnvVar !== undefined && resolvedUrl === undefined) {\n    if (\n      (TARGET_BUILD_TYPE === 'edge' ||\n        TARGET_BUILD_TYPE === 'wasm-engine-edge' ||\n        TARGET_BUILD_TYPE === 'wasm-compiler-edge') &&\n      getRuntime().id === 'workerd'\n    ) {\n      throw new PrismaClientInitializationError(\n        `error: Environment variable not found: ${datasourceUrl.fromEnvVar}.\n\nIn Cloudflare module Workers, environment variables are available only in the Worker's \\`env\\` parameter of \\`fetch\\`.\nTo solve this, provide the connection string directly: https://pris.ly/d/cloudflare-datasource-url`,\n        clientVersion,\n      )\n    }\n\n    // error matches as much as possible the usual engine error\n    throw new PrismaClientInitializationError(\n      `error: Environment variable not found: ${datasourceUrl.fromEnvVar}.`,\n      clientVersion,\n    )\n  }\n\n  // should not happen: no override, no env, no direct value\n  if (resolvedUrl === undefined) {\n    throw new PrismaClientInitializationError(\n      `error: Missing URL environment variable, value, or override.`,\n      clientVersion,\n    )\n  }\n\n  return resolvedUrl\n}\n", "export interface PrismaClientErrorInfo {\n  clientVersion: string\n  cause?: Error\n}\n\nexport abstract class PrismaClientError extends Error {\n  public abstract name: string\n  public abstract code: string\n  public clientVersion: string\n  public cause?: Error // like https://github.com/es-shims/error-cause\n\n  constructor(message: string, info: PrismaClientErrorInfo) {\n    super(message)\n\n    this.clientVersion = info.clientVersion\n    this.cause = info.cause\n  }\n\n  get [Symbol.toStringTag]() {\n    return this.name\n  }\n}\n", "import { PrismaClientError, type PrismaClientErrorInfo } from '../../../errors/PrismaClientError'\n\nexport interface DataProxyErrorInfo extends PrismaClientErrorInfo {\n  isRetryable?: boolean\n}\n\nexport abstract class DataProxyError extends PrismaClientError {\n  isRetryable: boolean\n\n  constructor(message: string, info: DataProxyErrorInfo) {\n    super(message, info)\n\n    this.isRetryable = info.isRetryable ?? true\n  }\n}\n", "export function setRetryable<T>(info: T, retryable: boolean) {\n  return {\n    ...info,\n    isRetryable: retryable,\n  }\n}\n", "import { setClassName } from '@prisma/internals'\n\nimport type { DataProxyErrorInfo } from './DataProxyError'\nimport { DataProxyError } from './DataProxyError'\nimport { setRetryable } from './utils/setRetryable'\n\nexport interface InvalidDatasourceErrorInfo extends DataProxyErrorInfo {}\nexport class InvalidDatasourceError extends DataProxyError {\n  public name = 'InvalidDatasourceError'\n  public code = 'P6001'\n\n  constructor(message: string, info: InvalidDatasourceErrorInfo) {\n    super(message, setRetryable(info, false))\n  }\n}\nsetClassName(InvalidDatasourceError, 'InvalidDatasourceError')\n", "import { isPrismaPostgresDev, PRISMA_POSTGRES_PROTOCOL } from '@prisma/internals'\n\nimport { resolveDatasourceUrl } from '../../../init/resolveDatasourceUrl'\nimport { InvalidDatasourceError } from '../../data-proxy/errors/InvalidDatasourceError'\nimport { EngineConfig } from '../Engine'\n\nexport interface GetUrlAndApiKeyOptions {\n  clientVersion: string\n  inlineDatasources: EngineConfig['inlineDatasources']\n  overrideDatasources: EngineConfig['overrideDatasources']\n  env: Record<string, string | undefined>\n}\n\nexport interface UrlAndApiKey {\n  url: HttpUrl\n  apiKey: string\n}\n\nexport type HttpUrl = URL & { protocol: 'http' | 'https' }\n\nexport function getUrlAndApiKey(options: GetUrlAndApiKeyOptions): UrlAndApiKey {\n  const errorInfo = { clientVersion: options.clientVersion }\n  const dsName = Object.keys(options.inlineDatasources)[0]\n  const serviceURL = resolveDatasourceUrl({\n    inlineDatasources: options.inlineDatasources,\n    overrideDatasources: options.overrideDatasources,\n    clientVersion: options.clientVersion,\n    env: { ...options.env, ...(typeof process !== 'undefined' ? process.env : {}) },\n  })\n\n  let url: URL\n  try {\n    url = new URL(serviceURL)\n  } catch {\n    throw new InvalidDatasourceError(\n      `Error validating datasource \\`${dsName}\\`: the URL must start with the protocol \\`prisma://\\``,\n      errorInfo,\n    )\n  }\n\n  const { protocol, searchParams } = url\n\n  if (protocol !== 'prisma:' && protocol !== PRISMA_POSTGRES_PROTOCOL) {\n    throw new InvalidDatasourceError(\n      `Error validating datasource \\`${dsName}\\`: the URL must start with the protocol \\`prisma://\\` or \\`prisma+postgres://\\``,\n      errorInfo,\n    )\n  }\n\n  const apiKey = searchParams.get('api_key')\n  if (apiKey === null || apiKey.length < 1) {\n    throw new InvalidDatasourceError(\n      `Error validating datasource \\`${dsName}\\`: the URL must contain a valid API key`,\n      errorInfo,\n    )\n  }\n\n  // To simplify things, `prisma dev`, for now, will not support HTTPS.\n  // In the future, if HTTPS for `prisma dev` becomes a thing, we'll need this line to be dynamic.\n  let httpScheme = isPrismaPostgresDev(url) ? 'http:' : 'https:'\n\n  if (process.env.TEST_CLIENT_ENGINE_REMOTE_EXECUTOR && url.searchParams.has('use_http')) {\n    httpScheme = 'http:'\n  }\n\n  // Switching from `prisma:` or `prisma+postgres:` to `http:` or `https:` by\n  // assigning to the `protocol` property is not allowed by the WHATWG URL API,\n  // it would be silently ignored without throwing an error. We have to manually\n  // update the protocol via string replacement.\n  const httpUrl = new URL(url.href.replace(protocol, httpScheme)) as HttpUrl\n\n  return { apiKey, url: httpUrl }\n}\n", "import type { QueryEngineLogLevel } from '@prisma/client-common'\nimport { enginesVersion } from '@prisma/engines-version'\nimport type { TracingHelper } from '@prisma/internals'\n\nexport type AccelerateHeaders = {\n  'Content-Type': string\n  'Prisma-Engine-Hash': string\n  'Prisma-Engine-Version': string\n  'X-Capture-Telemetry'?: string\n  'X-Transaction-Id'?: string\n  Accept: string\n  Authorization: string\n  traceparent?: string\n}\n\ntype HeaderBuilderOptions = {\n  traceparent?: string\n  transactionId?: string\n}\n\nexport class HeaderBuilder {\n  readonly apiKey: string\n  readonly tracingHelper: TracingHelper\n  readonly logLevel: QueryEngineLogLevel\n  readonly logQueries: boolean | undefined\n  readonly engineHash: string\n\n  constructor({\n    apiKey,\n    tracingHelper,\n    logLevel,\n    logQueries,\n    engineHash,\n  }: {\n    apiKey: string\n    tracingHelper: TracingHelper\n    logLevel: QueryEngineLogLevel\n    logQueries: boolean | undefined\n    engineHash: string\n  }) {\n    this.apiKey = apiKey\n    this.tracingHelper = tracingHelper\n    this.logLevel = logLevel\n    this.logQueries = logQueries\n    this.engineHash = engineHash\n  }\n\n  build({ traceparent, transactionId }: HeaderBuilderOptions = {}): AccelerateHeaders {\n    const headers: AccelerateHeaders = {\n      Accept: 'application/json',\n      Authorization: `Bearer ${this.apiKey}`,\n      'Content-Type': 'application/json',\n      'Prisma-Engine-Hash': this.engineHash,\n      'Prisma-Engine-Version': enginesVersion,\n    }\n\n    if (this.tracingHelper.isEnabled()) {\n      headers.traceparent = traceparent ?? this.tracingHelper.getTraceParent()\n    }\n\n    if (transactionId) {\n      headers['X-Transaction-Id'] = transactionId\n    }\n\n    const captureTelemetry = this.#buildCaptureSettings()\n\n    if (captureTelemetry.length > 0) {\n      headers['X-Capture-Telemetry'] = captureTelemetry.join(', ')\n    }\n\n    return headers\n  }\n\n  #buildCaptureSettings(): string[] {\n    const captureTelemetry: string[] = []\n\n    if (this.tracingHelper.isEnabled()) {\n      captureTelemetry.push('tracing')\n    }\n\n    if (this.logLevel) {\n      captureTelemetry.push(this.logLevel)\n    }\n\n    if (this.logQueries) {\n      captureTelemetry.push('query')\n    }\n\n    return captureTelemetry\n  }\n}\n", "export type EngineTimestamp = [seconds: number, nanoseconds: number]\n\n/**\n * Converts engine timestamp to JS timestamp, as accepted by `Date` constructor\n */\nexport function convertEngineTimestamp(timestamp: EngineTimestamp): number {\n  return timestamp[0] * 1e3 + timestamp[1] / 1e6\n}\n\n/**\n * Parses a `Date` from engine timestamp\n */\nexport function dateFromEngineTimestamp(timestamp: EngineTimestamp): Date {\n  return new Date(convertEngineTimestamp(timestamp))\n}\n", "import { setClassName } from '@prisma/internals'\n\nimport type { DataProxyErrorInfo } from './DataProxyError'\nimport { DataProxyError } from './DataProxyError'\nimport { setRetryable } from './utils/setRetryable'\n\nexport interface ForcedRetryErrorInfo extends DataProxyErrorInfo {}\n\nexport class ForcedRetryError extends DataProxyError {\n  public name = 'ForcedRetryError'\n  public code = 'P5001'\n\n  constructor(info: ForcedRetryErrorInfo) {\n    super('This request must be retried', setRetryable(info, true))\n  }\n}\nsetClassName(ForcedRetryError, 'ForcedRetryError')\n", "import { setClassName } from '@prisma/internals'\n\nimport type { DataProxyErrorInfo } from './DataProxyError'\nimport { DataProxyError } from './DataProxyError'\nimport { setRetryable } from './utils/setRetryable'\n\nexport interface NotImplementedYetErrorInfo extends DataProxyErrorInfo {}\n\nexport class NotImplementedYetError extends DataProxyError {\n  public name = 'NotImplementedYetError'\n  public code = 'P5004'\n\n  constructor(message: string, info: NotImplementedYetErrorInfo) {\n    super(message, setRetryable(info, false))\n  }\n}\nsetClassName(NotImplementedYetError, 'NotImplementedYetError')\n", "import type { DataProxyErrorInfo } from './DataProxyError'\nimport { DataProxyError } from './DataProxyError'\n\nexport interface DataProxyAPIErrorInfo extends DataProxyErrorInfo {\n  response: Response\n}\n\nexport abstract class DataProxyAPIError extends DataProxyError {\n  response: